<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
 post_only();$action=$_POST['action']??'';$id=(int)($_POST['id_usuario']??0);
 if($action==='delete'){$s=$pdo->prepare("SELECT COUNT(*) FROM prestamos WHERE id_usuario=? AND estado_prestamo='Activo'");$s->execute([$id]);if(!$id||(int)$s->fetchColumn()>0){flash('error','No se puede eliminar: el usuario tiene préstamos activos.');}else{$s=$pdo->prepare('SELECT COUNT(*) FROM prestamos WHERE id_usuario=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)flash('error','No se puede eliminar porque el historial conserva préstamos de este usuario.');else{$pdo->prepare("DELETE FROM usuarios WHERE id_usuario=? AND rol='Usuario'")->execute([$id]);flash('success','Usuario eliminado.');}}}
 else{$nombre=trim($_POST['nombre']??'');$doc=trim($_POST['documento']??'');$correo=strtolower(trim($_POST['correo']??''));if($nombre===''||$doc===''||!filter_var($correo,FILTER_VALIDATE_EMAIL)||mb_strlen($nombre)>100||mb_strlen($doc)>30||mb_strlen($correo)>150){flash('error','Revisa nombre, documento y correo.');}else{try{if($action==='edit'&&$id){$pdo->prepare("UPDATE usuarios SET nombre=?,documento=?,correo=? WHERE id_usuario=? AND rol='Usuario'")->execute([$nombre,$doc,$correo,$id]);flash('success','Usuario actualizado.');}elseif($action==='create'){$pdo->prepare("INSERT INTO usuarios(nombre,documento,correo,rol) VALUES(?,?,?,'Usuario')")->execute([$nombre,$doc,$correo]);flash('success','Usuario registrado.');}else flash('error','Operación inválida.');}catch(PDOException $ex){flash('error',$ex->getCode()==='23000'?'El documento o correo ya está registrado.':'No se pudo guardar el usuario.');}}}
 header('Location: usuarios.php');exit;
}
$q=trim($_GET['q']??'');$stmt=$pdo->prepare("SELECT * FROM usuarios WHERE rol='Usuario' AND (nombre LIKE ? OR documento LIKE ? OR correo LIKE ?) ORDER BY id_usuario DESC");$like='%'.$q.'%';$stmt->execute([$like,$like,$like]);$usuarios=$stmt->fetchAll();$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare("SELECT * FROM usuarios WHERE id_usuario=? AND rol='Usuario'");$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}
page_start('Usuarios','usuarios.php');
?>
<div class="page-heading"><div><span class="eyebrow">LECTORES</span><h1>Usuarios</h1><p>Las cuentas de lector tienen el rol Usuario; el rol Admin se gestiona por separado.</p></div></div>
<section class="panel mb-4"><h2><?= $edit?'Editar usuario':'Registrar usuario'; ?></h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="<?= $edit?'edit':'create'; ?>"><?php if($edit): ?><input type="hidden" name="id_usuario" value="<?= (int)$edit['id_usuario']; ?>"><?php endif; ?><div class="col-md-4"><label class="form-label">Nombre</label><input class="form-control" name="nombre" maxlength="100" required value="<?= e($edit['nombre']??''); ?>"></div><div class="col-md-3"><label class="form-label">Documento</label><input class="form-control" name="documento" maxlength="30" required value="<?= e($edit['documento']??''); ?>"></div><div class="col-md-4"><label class="form-label">Correo</label><input class="form-control" type="email" name="correo" maxlength="150" required value="<?= e($edit['correo']??''); ?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Guardar</button></div></form></section>
<section class="panel"><form method="get" class="d-flex gap-2 mb-3"><input class="form-control" name="q" placeholder="Buscar nombre, documento o correo" value="<?= e($q); ?>"><button class="btn btn-outline-primary">Buscar</button></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID</th><th>Nombre</th><th>Documento</th><th>Correo</th><th>Rol</th><th>Acciones</th></tr></thead><tbody>
<?php foreach($usuarios as $u): ?><tr><td><?= (int)$u['id_usuario']; ?></td><td><?= e($u['nombre']); ?></td><td><?= e($u['documento']); ?></td><td><?= e($u['correo']); ?></td><td><span class="badge text-bg-secondary">Usuario</span></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="usuarios.php?editar=<?= (int)$u['id_usuario']; ?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este usuario?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_usuario" value="<?= (int)$u['id_usuario']; ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td></tr><?php endforeach; ?><?php if(!$usuarios): ?><tr><td colspan="6" class="text-center text-secondary py-4">No hay usuarios registrados.</td></tr><?php endif; ?></tbody></table></div></section>
<?php page_end(); ?>
